SELECT SUM(Loss_Payment.Amount) AS Total_Loss, SUM(Loss_Reserve.Amount) AS Total_Loss_Reserved, SUM(Loss_Payment.Amount) - SUM(Loss_Reserve.Amount) AS Total_Loss_Reserved_Expense, SUM(Loss_Payment.Amount) - SUM(Loss_Reserve.Amount) AS Total_Loss_Reserved_Expense_Expense
FROM Loss_Payment
JOIN Loss_Reserve ON Loss_Payment.Policy_Amount_Identifier = Loss_Reserve.Policy_Amount_Identifier;

SELECT Claim_Identifier, SUM(Loss_Payment.Claim_Amount) AS Total_Loss
FROM Loss_Payment
GROUP BY Claim_Identifier;

SELECT Claim_Identifier, SUM(Loss_Payment.Claim_Amount) AS Total_Loss
FROM Loss_Payment
GROUP BY Claim_Identifier;

SELECT SUM(Loss_Payment.Claim_Amount) AS Loss_Payment_Total, SUM(Loss_Reserve.Claim_Amount) AS Loss_Reserve_Total, SUM(Loss_Payment.Claim_Amount) + SUM(Loss_Reserve.Claim_Amount) AS Total, SUM(Loss_Payment.Claim_Amount) * 1.0 / SUM(Loss_Reserve.Claim_Amount) AS Ratio
FROM Loss_Payment
JOIN Loss_Reserve ON Loss_Payment.Claim_Amount_Identifier = Loss_Reserve.Claim_Amount_Identifier;

SELECT Expense_Reserve.Claim_Amount_Identifier, Expense_Reserve.Amount_Type_Code, Expense_Reserve.Claim_Amount, Expense_Reserve.Insurance_Type_Code
FROM Expense_Reserve
JOIN Claim ON Expense_Reserve.Claim_Amount_Identifier = Claim.Claim_Amount_Identifier;

SELECT Expense_Reserve.Claim_Amount_Identifier, Expense_Reserve.Amount_Type_Code, Expense_Reserve.Claim_Amount, Expense_Reserve.Insurance_Type_Code
FROM Expense_Reserve
JOIN Claim ON Expense_Reserve.Claim_Amount_Identifier = Claim.Claim_Amount_Identifier;

SELECT DISTINCT Policy.Policy_Number, Claim.Claim_Number, Claim.Claim_Identifier, Claim.Claim_Open_Date, Claim.Claim_Close_Date, Claim.Claim_Reopen_Date, Claim.Claim_Reported_Date, Claim.Claim_Status_Code
FROM Policy
JOIN Claim ON Policy.Policy_Identifier = Claim.Policy_Identifier;

SELECT Expense_Payment.Claim_Amount_Identifier, Expense_Payment.Amount_Type_Code, Expense_Payment.Claim_Amount
FROM Expense_Payment
JOIN Claim ON Expense_Payment.Claim_Amount_Identifier = Claim.Claim_Amount_Identifier;
